import type { Def, Field, Fields, Schema, Ty, Variant } from "./ir.js";

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const RESERVED = new Set(["TyxFixedArray", "TyxMap", "TyxTypes"]);

/**
 * Emits TypeScript declarations for every type in the schema plus a `TyxTypes` map for `Codec`.
 * The declarations follow the runtime's value mapping; see the README.
 */
export function generateTypes(schema: Schema): string {
  const lines = [
    "// Generated by tyxrs from a tyx IR schema. Do not edit.",
    "",
    "export type TyxFixedArray<T, N extends number, R extends T[] = []> = R[\"length\"] extends N ? R : TyxFixedArray<T, N, [T, ...R]>;",
    "export type TyxMap<K, V> = K extends string ? { [key: string]: V } : [K, V][];",
    "",
  ];
  for (const def of schema.types) {
    lines.push(declaration(def), "");
  }
  const concrete = schema.types.filter((def) => (def.params?.length ?? 0) === 0);
  lines.push("export interface TyxTypes {");
  for (const def of concrete) lines.push(`  ${property(def.name)}: ${def.name};`);
  lines.push("}");
  return `${lines.join("\n")}\n`;
}

function declaration(def: Def): string {
  if (!IDENTIFIER.test(def.name)) throw new Error(`type name \`${def.name}\` is not a TypeScript identifier`);
  if (RESERVED.has(def.name)) throw new Error(`type name \`${def.name}\` collides with a generated helper`);
  const env = def.params ?? [];
  for (const param of env) {
    if (!IDENTIFIER.test(param)) throw new Error(`type parameter \`${param}\` of \`${def.name}\` is not a TypeScript identifier`);
    if (RESERVED.has(param)) throw new Error(`type parameter \`${param}\` of \`${def.name}\` collides with a generated helper`);
  }
  const params = env.length === 0 ? "" : `<${env.join(", ")}>`;
  switch (def.kind) {
    case "newtype":
      return `export type ${def.name}${params} = ${ty(def.ty, env)};`;
    case "struct": {
      if (def.fields.style === "tuple") return `export type ${def.name}${params} = ${tuple(def.fields.fields, env)};`;
      if (def.fields.fields.length === 0) return `export type ${def.name}${params} = { [key: string]: never };`;
      const body = def.fields.fields.map(
        (field) => `  ${property(field.name ?? "")}${field.optional ? "?" : ""}: ${ty(field.ty, env)};`,
      );
      return `export interface ${def.name}${params} {\n${body.join("\n")}\n}`;
    }
    case "enum": {
      if (def.variants.length === 0) return `export type ${def.name}${params} = never;`;
      return `export type ${def.name}${params} =\n${def.variants.map((variant) => variantType(variant, env)).join("\n")};`;
    }
  }
}

function variantType(variant: Variant, env: readonly string[]): string {
  switch (variant.payload) {
    case "unit":
      return `  | ${JSON.stringify(variant.name)}`;
    case "newtype":
      return `  | { ${property(variant.name)}: ${ty(variant.ty, env)} }`;
    case "fields":
      return `  | { ${property(variant.name)}: ${fieldsType(variant.fields, env, "    ")} }`;
  }
}

function fieldsType(fields: Fields, env: readonly string[], indent: string): string {
  if (fields.style === "tuple") return tuple(fields.fields, env);
  if (fields.fields.length === 0) return "{ [key: string]: never }";
  const body = fields.fields.map(
    (field) => `${indent}  ${property(field.name ?? "")}${field.optional ? "?" : ""}: ${ty(field.ty, env)};`,
  );
  return `{\n${body.join("\n")}\n${indent}}`;
}

function tuple(fields: readonly Field[], env: readonly string[]): string {
  return `[${fields.map((field) => `${ty(field.ty, env)}${field.optional ? " | undefined" : ""}`).join(", ")}]`;
}

function ty(node: Ty, env: readonly string[]): string {
  switch (node.kind) {
    case "unit":
      return "null";
    case "bool":
      return "boolean";
    case "u8":
    case "u16":
    case "u32":
    case "i8":
    case "i16":
    case "i32":
    case "f32":
    case "f64":
      return "number";
    case "u64":
    case "i64":
      return "bigint";
    case "str":
    case "bytes":
    case "uuid":
    case "timestamp":
      return "string";
    case "option":
      return `${ty(node.of, env)} | null`;
    case "seq":
    case "set":
      return arrayOf(ty(node.of, env));
    case "array":
      return `TyxFixedArray<${ty(node.of, env)}, ${node.len}>`;
    case "tuple":
      return `[${node.of.map((item) => ty(item, env)).join(", ")}]`;
    case "map":
      return node.key.kind === "str" ? `{ [key: string]: ${ty(node.value, env)} }` : `TyxMap<${ty(node.key, env)}, ${ty(node.value, env)}>`;
    case "named":
      return (node.args?.length ?? 0) === 0 ? node.name : `${node.name}<${node.args!.map((arg) => ty(arg, env)).join(", ")}>`;
    case "param": {
      const name = env[node.index];
      if (name === undefined) throw new Error(`unbound parameter $${node.index}`);
      return name;
    }
  }
}

function arrayOf(inner: string): string {
  return inner.includes(" | ") ? `(${inner})[]` : `${inner}[]`;
}

function property(name: string): string {
  return IDENTIFIER.test(name) ? name : JSON.stringify(name);
}
